  /**
   * Spec
   *
   * none, current, or needs_review (adopted, or behind the agent)
   */
  spec?: 'none' | 'current' | 'needs_review' | null;
  /**
   * Spec Version
   *
   * Its latest spec version
   */
  spec_version?: number | null;
